; ugtest.asm -- UGTEST.EXE: the M stand test program (MAME, DSS).
;
; Loads one UNET-GAME DLL with the embedded libman (L1 into WIN1), plays
; the gateway (ISA lock byte, #1FFD / #9FBD shadows, context, slots, event
; queue and UART ring in WIN2), keeps now_ms from the CTC2/CTC3 chain (the
; Worms set-up: /112 -> /156, polled, no interrupt), runs one scenario and
; leaves a text report in memory (UG_REPORT) for tools/mame/ugstand.lua.
;
; Build: tools/mame/run_m.py (sjasmplus, -D SCEN=<char>, the include
; generated by tools/mame/mkcfg.js: memory map + INIT_CONFIG block).
; Scenarios: 'E' echo 300 bytes, 'S' 8 KiB stream, 'P' the peer closes
; (TCP), 'D' SHUTDOWN with the channel open.
;
; This is application code: it may call DSS and wait.  ESP builds: before
; the DLL is loaded the program plays NETUP once (AT, AT+UART_CUR with
; RTS/CTS), as the ТЗ leaves the module set-up to the system tools.

	DEVICE	NOSLOT64K

	INCLUDE	"UNETGAME.INC"
	INCLUDE	"unetg_ctx.inc"		; ctx.out_hl, ctx.hw_state (this repository's own tool)
	INCLUDE	"ugcfg.inc"

	DEFINE	LIBMAN_MAX_LIBS 1
	DEFINE	LIBMAN_NO_LEGACY_API
	DEFINE	LIBMAN_L0_L1_ONLY

EXE_HEADER_SIZE	EQU	0x200
EXE_LOAD	EQU	0x8100
STACK_TOP	EQU	UG_MSTK + UG_MSTK_LEN
DSS		EQU	0x10
DSS_EXIT	EQU	0x41
DSS_PCHARS	EQU	0x5C
P_SYS		EQU	0x3C		; SYS port, user mode
STEP_BUDGET	EQU	500
UHW_RUN		EQU	2
SH_1FFD		EQU	0x01		; DSS value: RAM in WIN0, ISA closed
SH_9FBD		EQU	0x00
UART		EQU	0xC000 + UG_IO_BASE	; the card's io_base in the ISA window

	; UG_HW (the Ж / real-hardware stand, tools/hw/build_hw.sh): the
	; scenario comes from the DSS command line (ughw.inc hw_args) instead
	; of -DSCEN, a file replaces the M-stand's .spin, and extra core-cost
	; and latency measurements run.  Default off, so a plain build (no
	; -DUG_HW) is the M-stand program unchanged.  ughw.inc is pulled in
	; further down, inside the ORG'd EXE image (see "UG_HW helpers") --
	; never here, before ORG: code assembled before the first ORG lands
	; near address 0, outside the loaded EXE, so a CALL into it would
	; jump into whatever happens to be there at runtime.
	IFNDEF	UG_HW
	DEFINE	UG_HW 0
	ENDIF

	ORG	EXE_LOAD - EXE_HEADER_SIZE
exe_header
	DB	"EXE", 1
	DD	EXE_HEADER_SIZE
	DW	0
	DS	6, 0
	DW	start
	DW	start
	DW	STACK_TOP
	DB	0
	DS	EXE_HEADER_SIZE - ($ - exe_header), 0
	ASSERT	$ == EXE_LOAD

start
	IF	UG_HW
	; IX = the DSS command-line buffer (load-#80, the PSP's lower half:
	; [IX+0] length, [IX+1].. text) -- save it before anything clobbers
	; IX (every export call below sets it for its own argument).
	LD	(cmdline_ptr),IX
	ENDIF
	LD	SP,STACK_TOP
	IF	UG_HW
	; parse it now, before anything can fail: `finish` names the saved
	; report after scen_char even when the run stops at the DLL load
	CALL	hw_args
	LD	A,(scen_char)
	CP	'E'
	JR	Z,.scen_ok
	CP	'S'
	JR	Z,.scen_ok
	CP	'P'
	JR	Z,.scen_ok
	CP	'D'
	JR	Z,.scen_ok
	CP	'K'
	JR	Z,.scen_ok
	LD	A,'E'			; unknown or absent -> E
	LD	(scen_char),A
.scen_ok
	ENDIF
	; turbo on (21 MHz, the v1 profile): SYS port, user mode, bit 1 = write
	; the turbo latch, bit 0 = its value (Worms ports.inc, P_SYS_OFF)
	LD	A,0x03
	OUT	(P_SYS),A
	CALL	rep_init
	LD	HL,s_title
	CALL	rp_str
	LD	HL,dll_name
	CALL	rp_str
	CALL	rp_nl
	IF	UG_HW
	LD	HL,s_scen
	CALL	rp_str
	LD	A,(scen_char)
	CALL	rp_char
	CALL	rp_nl
	ENDIF
	CALL	tick_install
	CALL	ctc_init
	CALL	calibrate
	LD	HL,s_cal
	CALL	rp_str
	LD	HL,(cal_ctc)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(cal_loop)
	CALL	rp_hex16
	CALL	rp_nl
	; counts of STEP_BUDGET us: a frame is ~20.5 ms, 500 us ~ 1/41 of it
	LD	HL,(cal_ctc)
	LD	DE,41
	LD	BC,0
.lim
	OR	A
	SBC	HL,DE
	JR	C,.lim_ok
	INC	BC
	JR	.lim
.lim_ok
	LD	(st_lim),BC
	; gateway state
	LD	HL,UG_GW
	LD	(HL),0			; ISA lock free
	INC	HL
	LD	(HL),SH_1FFD
	INC	HL
	LD	(HL),SH_9FBD
	IF	UG_ESP
	CALL	netup
	ENDIF
	; load the DLL into WIN1 (libman calls INIT)
	LD	HL,dll_name
	LD	A,1
	CALL	LIBMAN.l_load
	JR	NC,.loaded
	LD	A,(LIBMAN.l_reason)	; why libman refused
	CALL	rp_hex8
	CALL	rp_nl
	LD	A,'L'
	JP	fail
.loaded
	LD	(dll_handle),HL
	LD	A,1
	LD	(dll_loaded),A
	; the application zeroes the context before the first INIT_CONFIG
	LD	HL,UG_CTX
	LD	DE,UG_CTX + 1
	LD	BC,UG_CTX_LEN - 1
	LD	(HL),0
	LDIR
	LD	IX,ginfo
	LD	DE,64
	LD	B,UNETG_GET_INFO
	CALL	dll
	LD	HL,s_info
	LD	DE,ginfo
	LD	B,64
	CALL	rp_dump
	LD	IX,cfg_block
	LD	B,UNETG_INIT_CONFIG
	CALL	dll
	PUSH	AF
	LD	HL,s_cfg
	CALL	rp_str
	POP	AF
	PUSH	AF
	CALL	rp_hex8
	CALL	rp_nl
	POP	AF
	OR	A
	LD	A,'C'
	JP	NZ,fail
	; bring-up (ESP: UART + AT set-up), at most 10 s
	LD	HL,10000
	CALL	dl_set
.hw
	CALL	pump
	LD	A,(UG_CTX + UCTX_HW_STATE)
	CP	UHW_RUN
	JR	Z,.hw_ok
	CALL	dl_due
	JR	NC,.hw
	LD	A,'H'
	JP	fail
.hw_ok
	LD	HL,s_hw
	CALL	rp_str
	IF	UG_HW
	CALL	hw_costs16		; channel idle: core-cost measurements first
	ENDIF
	CALL	scenario
	CALL	stats			; while the context is configured
	; SHUTDOWN until OK (3 s)
	LD	HL,s_shut
	CALL	rp_str
	LD	HL,3000
	CALL	dl_set
.shut
	LD	B,UNETG_SHUTDOWN
	CALL	dll
	OR	A
	JR	Z,.shut_ok
	CP	UNETG_STATUS_WORK
	JR	NZ,.shut_bad
	CALL	pump
	CALL	dl_due
	JR	NC,.shut
.shut_bad
	CALL	rp_hex8
	LD	A,'X'
	JP	fail
.shut_ok
	CALL	rp_nl
	LD	A,(fail_code)
	OR	A
	LD	A,'F'			; a soft failure (t, q): stats are already in
	JR	NZ,finish		; the report, `fail` would print them again
	LD	A,'P'
	JR	finish

; fail: A = reason code (letter)
fail
	LD	(fail_code),A
	LD	A,(dll_loaded)		; DLL loaded: statistics first
	OR	A
	JR	Z,.no_dll
	PUSH	AF
	CALL	stats
	POP	AF
.no_dll
	LD	A,'F'
finish
	LD	(UG_REPORT + RP_STATUS),A
	LD	A,(fail_code)
	LD	(UG_REPORT + RP_STATUS + 1),A
	CALL	rp_result
	; FINI and release
	LD	A,(dll_loaded)
	OR	A
	JR	Z,.freed
	XOR	A
	LD	(dll_loaded),A
	LD	HL,(dll_handle)
	CALL	LIBMAN.l_free
.freed
	CALL	ctc_stop
	IF	UG_HW
	; the report is already fully composed (rp_result ran in `finish`,
	; above): save it BEFORE the 0xA5 completion marker below, so a
	; harness polling once per video frame (M stand, ugstand.lua) can
	; never observe 0xA5 while hw_save is still running.
	CALL	hw_build_fname
	LD	HL,hw_fname
	CALL	hw_save
	ENDIF
	LD	HL,UG_REPORT + RP_TEXT
	LD	C,DSS_PCHARS
	RST	DSS
	LD	A,0xA5
	LD	(UG_REPORT + RP_STATUS + 2),A	; done: ugstand.lua collects the report
	IF	UG_HW
	; ugstand.lua waits 25 frames after it SEES 0xA5 before it actually
	; reads the report text ("let the DSS print finish"); outlast that
	; grace period (tick_remove is below, not above: wait_tick needs the
	; IM1 hook still installed) before hw_exit's DSS EXIT can disturb
	; anything the harness has not captured yet.
	LD	B,30
.hw_wait
	PUSH	BC			; wait_tick clobbers B
	CALL	wait_tick
	POP	BC
	DJNZ	.hw_wait
	CALL	tick_remove
	CALL	hw_exit			; does not return
	ELSE
	CALL	tick_remove
	ENDIF
.spin
	JR	.spin

rp_result
	LD	HL,s_result
	CALL	rp_str
	LD	A,(UG_REPORT + RP_STATUS)
	CP	'P'
	LD	HL,s_pass
	JR	Z,.r
	LD	HL,s_failr
	CALL	rp_str
	LD	A,(fail_code)
	CALL	rp_char
	LD	HL,s_crlf
.r
	JP	rp_str

; ----------------------------------------------------------------------
; Scenarios
; ----------------------------------------------------------------------
scenario
	CALL	open_wait
	IF	UG_HW
	; the scenario comes from the DSS command line (hw_args in `start`,
	; already checked: E/S/P/D/K, anything else became E), not -DSCEN
	LD	A,(scen_char)
	CP	'E'
	JR	Z,.hw_e
	CP	'S'
	JR	Z,.hw_s
	CP	'P'
	JR	Z,.hw_p
	CP	'D'
	JR	Z,.hw_d
	CP	'K'
	JR	Z,.hw_k
.hw_e
	LD	HL,300
	LD	(tx_total),HL
	CALL	send_all
	CALL	close_wait
	RET
.hw_s
	LD	HL,8192
	LD	(tx_total),HL
	CALL	send_all
	CALL	close_wait
	RET
.hw_p
	; the echo server closes after 64 bytes: PEER_CLOSED, then CLOSED
	LD	HL,64
	LD	(tx_total),HL
	CALL	send_all
	LD	HL,5000
	CALL	dl_set
.hw_pc
	CALL	pump
	LD	A,(ev_closed)
	OR	A
	JR	NZ,.hw_pc_done
	CALL	dl_due
	JR	NC,.hw_pc
	LD	A,'p'
	JP	fail
.hw_pc_done
	LD	A,(ev_peer)
	OR	A
	RET	NZ
	LD	A,'q'
	LD	(fail_code),A
	RET
.hw_d
	LD	HL,100
	LD	(tx_total),HL
	CALL	send_one
	LD	HL,200
	CALL	dl_set
.hw_dw
	CALL	pump
	CALL	dl_due
	JR	NC,.hw_dw
	RET
.hw_k
	CALL	soak
	RET
	ELSE
	IF	SCEN == 'E'
	LD	HL,300
	LD	(tx_total),HL
	CALL	send_all
	CALL	close_wait
	ENDIF
	IF	SCEN == 'S'
	LD	HL,8192
	LD	(tx_total),HL
	CALL	send_all
	CALL	close_wait
	ENDIF
	IF	SCEN == 'P'
	; the echo server closes after 64 bytes: PEER_CLOSED, then CLOSED
	LD	HL,64
	LD	(tx_total),HL
	CALL	send_all
	LD	HL,5000
	CALL	dl_set
.pc
	CALL	pump
	LD	A,(ev_closed)
	OR	A
	JR	NZ,.pc_done
	CALL	dl_due
	JR	NC,.pc
	LD	A,'p'
	JP	fail
.pc_done
	LD	A,(ev_peer)
	OR	A
	RET	NZ
	LD	A,'q'
	LD	(fail_code),A
	ENDIF
	IF	SCEN == 'D'
	LD	HL,100
	LD	(tx_total),HL
	CALL	send_one
	LD	HL,200
	CALL	dl_set
.d
	CALL	pump
	CALL	dl_due
	JR	NC,.d
	ENDIF
	RET
	ENDIF

; open_wait: OPEN, CONNECTED within 15 s
open_wait
	LD	HL,s_open
	CALL	rp_str
	LD	IX,0
	LD	B,UNETG_OPEN
	CALL	dll
	OR	A
	LD	A,'O'
	JP	NZ,fail
	LD	HL,15000
	CALL	dl_set
.w
	CALL	pump
	LD	A,(ev_connected)
	OR	A
	RET	NZ
	LD	A,(ev_closed)
	OR	A
	LD	A,'R'
	JP	NZ,fail
	CALL	dl_due
	JR	NC,.w
	LD	A,'T'
	JP	fail

; send_all: tx_total bytes in slot-size pieces, the echo checked, 30 s
send_all
	LD	HL,30000
	CALL	dl_set
.loop
	CALL	send_one
	CALL	pump
	LD	HL,(rx_count)
	LD	DE,(tx_total)
	OR	A
	SBC	HL,DE
	JR	NC,.done
	CALL	dl_due
	JR	NC,.loop
	LD	A,'E'
	JP	fail
.done
	LD	A,(rx_bad)
	OR	A
	LD	A,'B'
	JP	NZ,fail
	LD	HL,s_echo
	CALL	rp_str
	LD	HL,(rx_count)
	CALL	rp_hex16
	JP	rp_nl

; send_one: one TX slot of the pattern when there is room
send_one
	LD	HL,(tx_total)
	LD	DE,(tx_sent)
	OR	A
	SBC	HL,DE
	RET	Z
	LD	DE,UG_SLOT
	CALL	min_de_hl		; DE = this piece
	PUSH	DE
	LD	B,UNETG_TX_RESERVE
	CALL	dll
	POP	BC			; BC = piece
	OR	A
	RET	NZ			; no free slot yet
	LD	A,E
	LD	(tx_slot),A
	LD	HL,(UG_CTX + UCTX_OUT_HL)
	PUSH	BC
	LD	A,(tx_gen)
.fill
	LD	(HL),A
	ADD	A,31
	INC	HL
	DEC	BC
	LD	E,A
	LD	A,B
	OR	C
	LD	A,E
	JR	NZ,.fill
	LD	(tx_gen),A
	POP	DE			; length
	PUSH	DE
	LD	A,(tx_slot)
	LD	IX,(tx_tag)
	IF	UG_HW
	; LAT (ТЗ §8.3, see lat_on_txdone/lat_mark_echo): one measurement in
	; flight at a time -- arm a new one only while idle (lat_state == 0).
	; DE (piece length) and IX (tag) survive ctc_phase untouched; A is
	; the only register it clobbers besides HL.
	PUSH	AF
	LD	A,(lat_state)
	OR	A
	JR	NZ,.lat_skip
	CALL	ctc_phase
	LD	(lat_t0),HL
	LD	A,(ticks)
	LD	(lat_tick0),A
	LD	HL,(tx_tag)
	LD	(lat_tag),HL
	LD	HL,(tx_sent)
	ADD	HL,DE
	LD	(lat_target_rx),HL
	LD	A,1
	LD	(lat_state),A
.lat_skip
	POP	AF
	ENDIF
	LD	B,UNETG_TX_COMMIT
	CALL	dll
	POP	DE
	OR	A
	LD	A,'K'
	JP	NZ,fail
	LD	HL,(tx_sent)
	ADD	HL,DE
	LD	(tx_sent),HL
	LD	HL,(tx_tag)
	INC	HL
	LD	(tx_tag),HL
	RET

; close_wait: CLOSE, CLOSED within 5 s
close_wait
	LD	B,UNETG_CLOSE
	CALL	dll
	OR	A
	LD	A,'c'
	JP	NZ,fail
	LD	HL,5000
	CALL	dl_set
.w
	CALL	pump
	LD	A,(ev_closed)
	OR	A
	RET	NZ
	CALL	dl_due
	JR	NC,.w
	LD	A,'d'
	JP	fail

; ----------------------------------------------------------------------
; pump: one STEP, its events and the RX data (pattern checked)
; ----------------------------------------------------------------------
pump
	CALL	clk_update
	CALL	ctc_phase
	LD	(st_t0),HL
	LD	IX,(now_ms)
	LD	IY,(now_ms + 2)
	LD	DE,STEP_BUDGET
	XOR	A
	LD	B,UNETG_STEP
	CALL	dll
	CALL	ctc_phase
	LD	DE,(st_t0)
	OR	A
	SBC	HL,DE			; modulo the 65536-count CTC3 period
	IF	UG_HW
	LD	(st_last),HL		; this call's delta, for soak's per-frame accounting
	ENDIF
	; STEP time statistics (CTC counts, 875 kHz): n, sum, > 500 us, max
	PUSH	HL
	LD	DE,(st_n)
	INC	DE
	LD	(st_n),DE
	LD	DE,(st_sum)
	ADD	HL,DE
	LD	(st_sum),HL
	JR	NC,.sum_ok
	LD	HL,(st_sum + 2)
	INC	HL
	LD	(st_sum + 2),HL
.sum_ok
	POP	HL
	PUSH	HL
	LD	DE,(st_lim)		; counts of STEP_BUDGET us (from the calibration)
	OR	A
	SBC	HL,DE
	JR	C,.in_budget
	LD	HL,(st_over)
	INC	HL
	LD	(st_over),HL
.in_budget
	POP	HL
	LD	DE,(st_max)
	PUSH	HL
	OR	A
	SBC	HL,DE
	POP	HL
	JR	C,.events
	LD	(st_max),HL
.events
	LD	B,8
.ev
	PUSH	BC
	LD	IX,evbuf
	LD	B,UNETG_NEXT_EVENT
	CALL	dll
	POP	BC
	OR	A
	JR	NZ,.rx
	CALL	event
	DJNZ	.ev
.rx
	LD	B,4
.peek
	PUSH	BC
	LD	B,UNETG_RX_PEEK
	CALL	dll
	OR	A
	JR	NZ,.rx_end
	; DE = length, data at ctx.out_hl
	LD	HL,(UG_CTX + UCTX_OUT_HL)
	LD	A,(rx_gen)
	LD	C,A
.cmp
	LD	A,D
	OR	E
	JR	Z,.cmp_end
	LD	A,(HL)
	CP	C
	JR	Z,.same
	LD	A,1
	LD	(rx_bad),A
.same
	LD	A,C
	ADD	A,31
	LD	C,A
	INC	HL
	DEC	DE
	PUSH	HL
	LD	HL,(rx_count)
	INC	HL
	LD	(rx_count),HL
	POP	HL
	JR	.cmp
.cmp_end
	LD	A,C
	LD	(rx_gen),A
	LD	B,UNETG_RX_RELEASE
	CALL	dll
	POP	BC
	DJNZ	.peek
	JR	.pump_tail
.rx_end
	POP	BC
.pump_tail
	IF	UG_HW
	LD	A,(lat_state)
	CP	2
	JR	NZ,.lat_pump_skip
	LD	HL,(rx_count)
	LD	DE,(lat_target_rx)
	OR	A
	SBC	HL,DE
	JR	C,.lat_pump_skip	; the echo has not fully arrived yet
	CALL	lat_mark_echo
.lat_pump_skip
	ENDIF
	RET

; event: evbuf holds one event; flags + a report entry "tt/ss "
event
	LD	A,(evbuf + UNETG_EVT_TYPE)
	CP	UNETG_EV_CONNECTED
	JR	NZ,.e1
	LD	(ev_connected),A
.e1
	CP	UNETG_EV_CLOSED
	JR	NZ,.e2
	LD	(ev_closed),A
.e2
	CP	UNETG_EV_PEER_CLOSED
	JR	NZ,.e3
	LD	(ev_peer),A
.e3
	CP	UNETG_EV_RX_READY
	RET	Z			; not logged (frequent)
	CP	UNETG_EV_TX_DONE
	JR	NZ,.log
	LD	A,(evbuf + UNETG_EVT_STATUS)
	IF	UG_HW
	CALL	lat_on_txdone		; preserves A
	ENDIF
	OR	A
	RET	Z			; TX_DONE OK: not logged
	CP	UNETG_TXDONE_CANCEL	; ABI §5: CANCEL is the documented outcome
	JR	Z,.txcancel		; of ABORT/SHUTDOWN on an unfinished TX, not a failure
	LD	A,'t'
	LD	(fail_code),A
.txcancel
	LD	A,(evbuf + UNETG_EVT_TYPE)
.log
	PUSH	AF
	LD	HL,s_ev
	CALL	rp_str
	POP	AF
	CALL	rp_hex8
	LD	A,'/'
	CALL	rp_char
	LD	A,(evbuf + UNETG_EVT_DETAIL)
	CALL	rp_hex8
	JP	rp_nl

; stats: GET_STATS dump, STEP times and the cost of a trivial export call
; (RX_PEEK with nothing to read: libman + dispatch), all in CTC counts
stats
	CALL	ctc_phase
	LD	(st_t0),HL
	LD	B,16
.call
	PUSH	BC
	LD	B,UNETG_RX_PEEK
	CALL	dll
	POP	BC
	DJNZ	.call
	CALL	ctc_phase
	LD	DE,(st_t0)
	OR	A
	SBC	HL,DE
	PUSH	HL
	LD	HL,s_calltime
	CALL	rp_str
	POP	HL
	CALL	rp_hex16
	CALL	rp_nl
	LD	IX,gstats
	LD	DE,80
	LD	B,UNETG_GET_STATS
	CALL	dll
	LD	HL,s_stats
	LD	DE,gstats
	LD	B,80
	CALL	rp_dump
	LD	HL,s_maxstep
	CALL	rp_str
	LD	HL,(st_max)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(st_n)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(st_sum + 2)
	CALL	rp_hex16
	LD	HL,(st_sum)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(st_over)
	CALL	rp_hex16
	CALL	rp_nl
	LD	HL,s_now
	CALL	rp_str
	CALL	clk_update
	LD	HL,(now_ms + 2)
	CALL	rp_hex16
	LD	HL,(now_ms)
	CALL	rp_hex16
	CALL	rp_nl
	IF	UG_HW
	CALL	lat_report
	ENDIF
	RET

; dll: call export B with A, DE, IX, IY; returns A, DE.  libman refusal
; (CF) is fatal.
dll
	PUSH	AF
	LD	HL,(dll_handle)
	POP	AF
	CALL	LIBMAN.l_call
	RET	NC
	LD	A,'M'
	LD	(fail_code),A
	LD	A,'F'
	JP	finish

min_de_hl				; DE = min(DE, HL)
	PUSH	HL
	OR	A
	SBC	HL,DE
	POP	HL
	RET	NC
	EX	DE,HL
	RET

	IF	UG_HW
; ----------------------------------------------------------------------
; UG_HW (Ж stand) only: hw_args/hw_save/hw_exit (ughw.inc), latency
; sampling, core-cost bursts, the soak scenario and the report file name.
; CTC counts throughout, like the rest of the report;
; tools/mame/ugreport.py scales by CAL.  ughw.inc is included here, not
; before ORG, so its code lands inside the loaded EXE image.
; ----------------------------------------------------------------------
	INCLUDE	"ughw.inc"

; lat_on_txdone: called from `event` with A = the TX_DONE status (kept).
; Checks evbuf's tag against the one send_one armed; a miss (another
; packet's TX_DONE, or no measurement in flight) does nothing; a FAILED or
; CANCEL TX_DONE of the armed packet drops the sample (no echo will
; come).  Preserves AF and BC (pump's event loop counter).
; Clobbers DE, HL.
lat_on_txdone
	PUSH	BC
	PUSH	AF
	LD	C,A
	LD	A,(lat_state)
	CP	1
	JR	NZ,.skip
	LD	HL,(evbuf + UNETG_EVT_TAG)
	LD	DE,(lat_tag)
	OR	A
	SBC	HL,DE
	JR	NZ,.skip
	LD	A,C
	OR	A
	JR	Z,.ok
	XOR	A
	LD	(lat_state),A
	JR	.skip
.ok
	CALL	lat_mark_txdone
.skip
	POP	AF
	POP	BC
	RET

; lat_elapsed: HL = ctc_phase - lat_t0 in CTC counts, or 0xFFFF (and
; lat_sat + 1) when the 16-bit CTC3 period (~50 ms) may have wrapped:
; frame ticks since the arm k >= 3, or k == 2 with less than one frame of
; counts (cal_ctc) -- the true time is then 50..60 ms, not the small
; remainder.  k <= 1 is under two frames (~41 ms), inside the period.
; Assumes no lost frame tick (CLOCK_RATE shows the ratio: real Sprinter
; ~1, MAME ~0.3 -- on M a long sample can hide as a short one).
; Clobbers A, BC, DE.
lat_elapsed
	CALL	ctc_phase
	LD	DE,(lat_t0)
	OR	A
	SBC	HL,DE
	LD	A,(lat_tick0)
	LD	B,A
	LD	A,(ticks)
	SUB	B
	CP	2
	RET	C
	JR	NZ,.sat
	LD	DE,(cal_ctc)
	PUSH	HL
	OR	A
	SBC	HL,DE
	POP	HL
	RET	NC
.sat
	LD	HL,lat_kmax		; A = k: the worst one, in frames
	CP	(HL)
	JR	C,.kmax
	LD	(HL),A
.kmax
	LD	HL,(lat_sat)
	INC	HL
	LD	(lat_sat),HL
	LD	HL,0xFFFF
	RET

; lat_mark_txdone: ctc_phase - lat_t0 into the txdone stats; lat_state -> 2
; (now waiting for the echo at lat_target_rx, armed by send_one).
; Clobbers A, BC, DE, HL.
lat_mark_txdone
	CALL	lat_elapsed
	LD	DE,(lat_txdone_max)
	PUSH	HL
	OR	A
	SBC	HL,DE
	POP	HL
	JR	C,.not_max
	LD	(lat_txdone_max),HL
.not_max
	LD	DE,(lat_txdone_sum)
	ADD	HL,DE
	LD	(lat_txdone_sum),HL
	JR	NC,.sum_nc
	LD	HL,(lat_txdone_sum + 2)
	INC	HL
	LD	(lat_txdone_sum + 2),HL
.sum_nc
	LD	HL,(lat_txdone_n)
	INC	HL
	LD	(lat_txdone_n),HL
	LD	A,2
	LD	(lat_state),A
	RET

; lat_mark_echo: called from pump once rx_count reaches lat_target_rx.
; ctc_phase - lat_t0 into the echo stats; lat_state -> 0 (idle: the next
; send_one may arm a new sample).  Clobbers A, BC, DE, HL.
lat_mark_echo
	CALL	lat_elapsed
	LD	DE,(lat_echo_max)
	PUSH	HL
	OR	A
	SBC	HL,DE
	POP	HL
	JR	C,.not_max
	LD	(lat_echo_max),HL
.not_max
	LD	DE,(lat_echo_sum)
	ADD	HL,DE
	LD	(lat_echo_sum),HL
	JR	NC,.sum_nc
	LD	HL,(lat_echo_sum + 2)
	INC	HL
	LD	(lat_echo_sum + 2),HL
.sum_nc
	LD	HL,(lat_echo_n)
	INC	HL
	LD	(lat_echo_n),HL
	XOR	A
	LD	(lat_state),A
	RET

; lat_report: "LAT n_txdone max_txdone sum_txdone(32) n_echo max_echo
; sum_echo(32) n_sat k_max" (CTC counts; the host computes the mean:
; sum/n; n_sat samples saturated at 0xFFFF -- each over 40 ms, see
; lat_elapsed -- the longest of them k_max frame ticks).  Echo
; fields stay 0 on a one-way stream (nothing ever reaches lat_mark_echo).
; For ESP, TX_DONE (SEND OK to the module) is not proof the frame left
; the air -- only the echo round trip is.
lat_report
	LD	HL,s_lat
	CALL	rp_str
	LD	HL,(lat_txdone_n)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(lat_txdone_max)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(lat_txdone_sum + 2)
	CALL	rp_hex16
	LD	HL,(lat_txdone_sum)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(lat_echo_n)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(lat_echo_max)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(lat_echo_sum + 2)
	CALL	rp_hex16
	LD	HL,(lat_echo_sum)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(lat_sat)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	A,(lat_kmax)
	CALL	rp_hex8
	JP	rp_nl

; hw_costs16: ISRTIME16 (16 x STEP_ISR source=TIMER, budget 150, the
; gateway's own ISR-path burst), BUSYTIME16 (the same burst with the ISA
; lock held by another owner: the BUS_BUSY path) and EMPTYSTEP16 (16 x
; STEP with nothing pending) -- one DI section each, in CTC counts.
; Call once, channel idle, right after bring-up.  Clobbers everything
; `dll` and ctc_phase do.
hw_costs16
	DI
	CALL	ctc_phase
	LD	(hc_t0),HL
	LD	B,16
.isr
	PUSH	BC
	LD	A,UNETG_SRC_TIMER
	LD	DE,150
	LD	B,UNETG_STEP_ISR
	CALL	dll
	POP	BC
	DJNZ	.isr
	CALL	ctc_phase
	LD	DE,(hc_t0)
	OR	A
	SBC	HL,DE
	EI
	LD	(hc_isr),HL

	LD	A,3				; owner 3 (sound): not net/main(1), not net/ISR(2)
	LD	(UG_GW),A
	DI
	CALL	ctc_phase
	LD	(hc_t0),HL
	LD	B,16
.busy
	PUSH	BC
	LD	A,UNETG_SRC_TIMER
	LD	DE,150
	LD	B,UNETG_STEP_ISR
	CALL	dll
	POP	BC
	DJNZ	.busy
	CALL	ctc_phase
	LD	DE,(hc_t0)
	OR	A
	SBC	HL,DE
	EI
	LD	(hc_busy),HL
	XOR	A
	LD	(UG_GW),A			; release

	DI
	CALL	ctc_phase
	LD	(hc_t0),HL
	LD	B,16
.empty
	PUSH	BC
	CALL	clk_update
	LD	IX,(now_ms)
	LD	IY,(now_ms + 2)
	LD	DE,STEP_BUDGET
	XOR	A
	LD	B,UNETG_STEP
	CALL	dll
	POP	BC
	DJNZ	.empty
	CALL	ctc_phase
	LD	DE,(hc_t0)
	OR	A
	SBC	HL,DE
	EI
	LD	(hc_empty),HL

	LD	HL,s_isrtime
	CALL	rp_str
	LD	HL,(hc_isr)
	CALL	rp_hex16
	CALL	rp_nl
	LD	HL,s_busytime
	CALL	rp_str
	LD	HL,(hc_busy)
	CALL	rp_hex16
	CALL	rp_nl
	LD	HL,s_emptystep
	CALL	rp_str
	LD	HL,(hc_empty)
	CALL	rp_hex16
	JP	rp_nl

; soak_send_one: like send_one but unbounded (its own 32-bit byte count,
; no tx_total/tx_sent window).  RET with HL = bytes committed this call
; (0 = no free slot yet).  Clobbers A, BC, DE, HL, IX.
soak_send_one
	LD	DE,UG_SLOT
	LD	B,UNETG_TX_RESERVE
	CALL	dll
	OR	A
	JR	NZ,.none
	LD	A,E
	LD	(tx_slot),A
	LD	HL,(UG_CTX + UCTX_OUT_HL)
	LD	BC,UG_SLOT
	LD	A,(tx_gen)
.fill
	LD	(HL),A
	ADD	A,31
	INC	HL
	DEC	BC
	LD	E,A
	LD	A,B
	OR	C
	LD	A,E
	JR	NZ,.fill
	LD	(tx_gen),A
	LD	A,(tx_slot)
	LD	IX,(tx_tag)
	LD	DE,UG_SLOT
	LD	B,UNETG_TX_COMMIT
	CALL	dll
	OR	A
	LD	A,'K'
	JP	NZ,fail
	LD	HL,(tx_tag)
	INC	HL
	LD	(tx_tag),HL
	LD	HL,UG_SLOT
	RET
.none
	LD	HL,0
	RET

; soak: UG_HW scenario 'K' (minutes in hw_argnum, ТЗ §8.3).  A continuous
; two-way stream for hw_argnum real minutes (50 Hz frame ticks counted by
; `ticks`: 3000/min), the RX pattern checked by pump exactly as every
; other scenario (rx_bad is sticky).  Per-frame STEP-time totals (not the
; whole-run max/mean of `stats`) catch one bad 20 ms window that an
; overall average would hide.  Reports raw 32-bit accumulators -- no
; on-device division, tools/measure/parse_hw.py computes the means:
; SOAK frames(32) net_max net_sum(32) bytes(32) rx_bad
soak
	LD	HL,0
	LD	(soak_framesleft),HL
	LD	(soak_framesleft + 2),HL
	LD	(soak_frames),HL
	LD	(soak_frames + 2),HL
	LD	(soak_netcur),HL
	LD	(soak_netmax),HL
	LD	(soak_netsum),HL
	LD	(soak_netsum + 2),HL
	LD	(soak_bytes),HL
	LD	(soak_bytes + 2),HL
	LD	A,(ticks)
	LD	(soak_tick0),A
	LD	HL,(hw_argnum)
	LD	A,H
	OR	L
	JR	NZ,.have_min
	LD	HL,1				; 0 (no argument) -> 1 minute, not a no-op
.have_min
.mul_loop
	LD	A,H
	OR	L
	JR	Z,.mul_done
	PUSH	HL
	LD	HL,(soak_framesleft)
	LD	DE,3000
	ADD	HL,DE
	LD	(soak_framesleft),HL
	JR	NC,.mul_nc
	LD	HL,(soak_framesleft + 2)
	INC	HL
	LD	(soak_framesleft + 2),HL
.mul_nc
	POP	HL
	DEC	HL
	JR	.mul_loop
.mul_done
.loop
	CALL	soak_send_one
	LD	DE,(soak_bytes)
	ADD	HL,DE
	LD	(soak_bytes),HL
	JR	NC,.bytes_nc
	LD	HL,(soak_bytes + 2)
	INC	HL
	LD	(soak_bytes + 2),HL
.bytes_nc
	CALL	pump
	LD	HL,(st_last)
	LD	DE,(soak_netcur)
	ADD	HL,DE
	JR	NC,.cur_nc
	LD	HL,0xFFFF		; saturate (lost frame ticks make a long "frame")
.cur_nc
	LD	(soak_netcur),HL
	LD	A,(ev_closed)
	OR	A
	JR	NZ,.done		; the channel is gone (TIMEOUT, peer): report what ran
	LD	A,(ticks)
	LD	B,A
	LD	A,(soak_tick0)
	CP	B
	JR	Z,.loop				; no frame boundary yet, keep streaming
	LD	A,B
	LD	(soak_tick0),A
	LD	HL,(soak_netcur)
	LD	DE,(soak_netmax)
	OR	A
	SBC	HL,DE
	JR	C,.not_max
	LD	HL,(soak_netcur)
	LD	(soak_netmax),HL
.not_max
	LD	HL,(soak_netcur)
	LD	DE,(soak_netsum)
	ADD	HL,DE
	LD	(soak_netsum),HL
	JR	NC,.sum_nc
	LD	HL,(soak_netsum + 2)
	INC	HL
	LD	(soak_netsum + 2),HL
.sum_nc
	LD	HL,0
	LD	(soak_netcur),HL
	LD	HL,(soak_frames)
	INC	HL
	LD	(soak_frames),HL
	LD	A,H			; INC HL sets no flags: test the low word
	OR	L
	JR	NZ,.frames_nc
	LD	HL,(soak_frames + 2)
	INC	HL
	LD	(soak_frames + 2),HL
.frames_nc
	LD	HL,(soak_framesleft)
	LD	DE,1
	OR	A
	SBC	HL,DE
	LD	(soak_framesleft),HL
	JR	NC,.fl_nc
	LD	HL,(soak_framesleft + 2)
	DEC	HL
	LD	(soak_framesleft + 2),HL
.fl_nc
	LD	HL,(soak_framesleft)
	LD	A,H
	OR	L
	JP	NZ,.loop
	LD	HL,(soak_framesleft + 2)
	LD	A,H
	OR	L
	JP	NZ,.loop
.done
	LD	HL,s_soak
	CALL	rp_str
	LD	HL,(soak_frames + 2)
	CALL	rp_hex16
	LD	HL,(soak_frames)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(soak_netmax)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(soak_netsum + 2)
	CALL	rp_hex16
	LD	HL,(soak_netsum)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	HL,(soak_bytes + 2)
	CALL	rp_hex16
	LD	HL,(soak_bytes)
	CALL	rp_hex16
	LD	A,' '
	CALL	rp_char
	LD	A,(rx_bad)
	CALL	rp_hex8
	JP	rp_nl

s_scen		DB	"SCEN ", 0
s_lat		DB	"LAT ", 0
s_isrtime	DB	"ISRTIME16 ", 0
s_busytime	DB	"BUSYTIME16 ", 0
s_emptystep	DB	"EMPTYSTEP16 ", 0
s_soak		DB	"SOAK ", 0

hc_t0		DW	0
hc_isr		DW	0
hc_busy		DW	0
hc_empty	DW	0

lat_state	DB	0			; 0 idle, 1 waiting TX_DONE, 2 waiting echo
lat_tag		DW	0
lat_t0		DW	0
lat_tick0	DB	0
lat_sat		DW	0
lat_kmax	DB	0
lat_target_rx	DW	0
lat_txdone_n	DW	0
lat_txdone_max	DW	0
lat_txdone_sum	DD	0
lat_echo_n	DW	0
lat_echo_max	DW	0
lat_echo_sum	DD	0

st_last		DW	0			; pump's last STEP delta (soak's per-frame sum)
soak_framesleft	DD	0
soak_frames	DD	0
soak_netcur	DW	0
soak_netmax	DW	0
soak_netsum	DD	0
soak_bytes	DD	0
soak_tick0	DB	0
	ENDIF

	INCLUDE	"ugbase.inc"		; frame hook, CTC durations, deadlines, report

; ----------------------------------------------------------------------
; NETUP role (ESP): module UART at 115200 8N1 with RTS/CTS, as
; sprinter_wifi/network NETUP does (AT+UART_CUR=...,3).
; ----------------------------------------------------------------------
	IF	UG_ESP
netup
	CALL	isa_open
	LD	HL,UART + 1
	LD	(HL),0			; IER
	LD	HL,UART + 3
	LD	(HL),0x83		; DLAB
	LD	HL,UART
	LD	(HL),8			; 115200 at 14.7456 MHz
	INC	HL
	LD	(HL),0
	LD	HL,UART + 3
	LD	(HL),0x03		; 8N1
	LD	HL,UART + 2
	LD	(HL),0x87		; FIFO, resets, trigger 8
	LD	HL,UART + 4
	LD	(HL),0x22		; AFE + RTS
	CALL	isa_close
	LD	HL,s_at
	CALL	at_cmd
	LD	HL,s_uartcur
	CALL	at_cmd
	RET

; at_cmd: send the AT line at HL, collect the answer for up to 1 s into the
; report (until "OK" or "ERROR").
at_cmd
	PUSH	HL
	LD	A,'>'
	CALL	rp_char
	POP	HL
	PUSH	HL
	CALL	rp_str
	POP	HL
.send
	LD	A,(HL)
	OR	A
	JR	Z,.sent
	PUSH	HL
	CALL	isa_open
.thre
	LD	A,(UART + 5)
	AND	0x20
	JR	Z,.thre
	POP	HL
	LD	A,(HL)
	LD	(UART),A
	CALL	isa_close
	INC	HL
	JR	.send
.sent
	LD	HL,1000
	CALL	dl_set
	XOR	A
	LD	(at_ok),A
.rx
	CALL	isa_open
	LD	A,(UART + 5)
	RRA
	JR	NC,.none
	LD	A,(UART)
	CALL	isa_close
	CP	10
	JR	Z,.rx
	CALL	rp_char
	CP	'K'			; "OK" (an ERROR waits for the 1 s end)
	JR	Z,.done
	JR	.rx
.none
	CALL	isa_close
	CALL	dl_due
	JR	NC,.rx
.done
	JP	rp_nl

isa_open
	DI
	IN	A,(0xE2)
	LD	(isa_e2),A
	LD	BC,0x1FFD
	LD	A,SH_1FFD | 0x10
	OUT	(C),A
	LD	A,0xD4 | (UG_ISA_SLOT << 1)	; the card's ISA slot, I/O space (slot 1: #D6)
	LD	BC,0x00E2
	OUT	(C),A
	XOR	A
	LD	BC,0x9FBD
	OUT	(C),A
	RET
isa_close
	PUSH	AF
	LD	BC,0x9FBD
	LD	A,SH_9FBD
	OUT	(C),A
	LD	BC,0x1FFD
	LD	A,SH_1FFD
	OUT	(C),A
	LD	A,(isa_e2)
	LD	BC,0x00E2
	OUT	(C),A
	POP	AF
	EI
	RET
	ENDIF

